/* LearnForge — Global Styles */
:root {
  --black: #000000;
  --lime: #E6FF32;
  --burgundy: #7F2A23;
  --white: #ffffff;
  --gray-50: #f9fafb;
  --gray-100: #f3f4f6;
  --gray-200: #e5e7eb;
  --gray-400: #9ca3af;
  --gray-600: #4b5563;
  --gray-700: #374151;
  --gray-800: #1f2937;
  --radius: 12px;
  --radius-lg: 20px;
  --shadow: 0 4px 24px rgba(0,0,0,0.08);
  --shadow-lg: 0 8px 40px rgba(0,0,0,0.12);
  --transition: 0.25s cubic-bezier(0.4,0,0.2,1);
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;
  color: var(--black);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

/* ── Typography ── */
h1 { font-size: clamp(2.2rem, 5vw, 3.8rem); font-weight: 800; line-height: 1.1; letter-spacing: -0.02em; }
h2 { font-size: clamp(1.8rem, 3.5vw, 2.8rem); font-weight: 700; line-height: 1.2; letter-spacing: -0.01em; }
h3 { font-size: clamp(1.2rem, 2vw, 1.5rem); font-weight: 600; line-height: 1.3; }
h4 { font-size: 1.1rem; font-weight: 600; }
p { color: var(--gray-700); }
a { text-decoration: none; color: inherit; }

/* ── Layout ── */
.container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
.section { padding: 80px 0; }
.section-sm { padding: 56px 0; }
.text-center { text-align: center; }

/* ── Buttons ── */
.btn {
  display: inline-flex; align-items: center; justify-content: center;
  padding: 14px 28px; border-radius: 8px; font-weight: 600; font-size: 0.95rem;
  cursor: pointer; transition: var(--transition); border: none; gap: 8px;
  white-space: nowrap;
}
.btn-primary {
  background: var(--black); color: var(--lime);
}
.btn-primary:hover { background: #111; transform: translateY(-1px); box-shadow: 0 6px 20px rgba(0,0,0,0.25); }
.btn-lime {
  background: var(--lime); color: var(--black);
}
.btn-lime:hover { background: #d4ee20; transform: translateY(-1px); box-shadow: 0 6px 20px rgba(230,255,50,0.4); }
.btn-outline {
  background: transparent; color: var(--black); border: 2px solid var(--black);
}
.btn-outline:hover { background: var(--black); color: var(--white); }
.btn-outline-white {
  background: transparent; color: var(--white); border: 2px solid rgba(255,255,255,0.5);
}
.btn-outline-white:hover { background: rgba(255,255,255,0.15); border-color: var(--white); }
.btn-lg { padding: 18px 36px; font-size: 1.05rem; }

/* ── Navigation ── */
.nav {
  position: sticky; top: 0; z-index: 100;
  background: rgba(255,255,255,0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--gray-200);
}
.nav-inner {
  display: flex; align-items: center; justify-content: space-between;
  padding: 16px 24px; max-width: 1200px; margin: 0 auto;
}
.nav-logo {
  font-size: 1.5rem; font-weight: 800; color: var(--black);
  display: flex; align-items: center; gap: 10px;
}
.nav-logo .logo-mark {
  width: 36px; height: 36px; background: var(--black); border-radius: 8px;
  display: flex; align-items: center; justify-content: center;
}
.nav-logo .logo-mark span {
  color: var(--lime); font-weight: 900; font-size: 1.1rem;
}
.nav-links {
  display: flex; align-items: center; gap: 4px; list-style: none;
}
.nav-links a {
  padding: 8px 14px; border-radius: 6px; font-size: 0.9rem; font-weight: 500; color: var(--gray-700);
  transition: var(--transition);
}
.nav-links a:hover, .nav-links a.active { background: var(--gray-100); color: var(--black); }
.nav-cta { display: flex; align-items: center; gap: 12px; }
.nav-toggle { display: none; background: none; border: none; cursor: pointer; padding: 8px; }

/* ── Hero ── */
.hero {
  background: var(--black); color: var(--white); padding: 100px 0 80px;
  position: relative; overflow: hidden;
}
.hero::before {
  content: ''; position: absolute; inset: 0;
  background: radial-gradient(ellipse 60% 50% at 50% -10%, rgba(230,255,50,0.15) 0%, transparent 70%);
  pointer-events: none;
}
.hero-content { position: relative; z-index: 1; text-align: center; max-width: 800px; margin: 0 auto; }
.hero h1 { color: var(--white); margin-bottom: 24px; }
.hero h1 em { color: var(--lime); font-style: normal; }
.hero p { font-size: 1.15rem; color: rgba(255,255,255,0.8); margin-bottom: 40px; max-width: 600px; margin-left: auto; margin-right: auto; }
.hero-ctas { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; margin-bottom: 48px; }

/* Hero Tab Switcher */
.hero-tabs {
  display: flex; gap: 8px; justify-content: center; margin-bottom: 32px;
}
.hero-tab {
  padding: 10px 24px; border-radius: 50px; font-size: 0.9rem; font-weight: 600;
  cursor: pointer; transition: var(--transition); border: 2px solid rgba(255,255,255,0.2);
  background: transparent; color: rgba(255,255,255,0.7);
}
.hero-tab.active { background: var(--lime); color: var(--black); border-color: var(--lime); }
.hero-preview {
  background: rgba(255,255,255,0.06); border: 1px solid rgba(255,255,255,0.12);
  border-radius: var(--radius-lg); padding: 32px; max-width: 700px; margin: 0 auto;
  backdrop-filter: blur(8px);
}
.hero-preview-panel { display: none; }
.hero-preview-panel.active { display: block; }
.preview-header {
  display: flex; align-items: center; gap: 12px; margin-bottom: 20px;
  padding-bottom: 16px; border-bottom: 1px solid rgba(255,255,255,0.1);
}
.preview-dot { width: 10px; height: 10px; border-radius: 50%; }
.preview-dot.red { background: #ff5f57; }
.preview-dot.yellow { background: #febc2e; }
.preview-dot.green { background: #28c840; }
.preview-title { font-size: 0.85rem; color: rgba(255,255,255,0.5); }
.preview-stats { display: grid; grid-template-columns: repeat(3,1fr); gap: 16px; }
.preview-stat { background: rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; text-align: center; }
.preview-stat .num { font-size: 1.4rem; font-weight: 800; color: var(--lime); }
.preview-stat .label { font-size: 0.75rem; color: rgba(255,255,255,0.6); margin-top: 4px; }
.preview-course-list { display: flex; flex-direction: column; gap: 10px; }
.preview-course-item {
  background: rgba(255,255,255,0.08); border-radius: 8px; padding: 12px 16px;
  display: flex; align-items: center; gap: 12px;
}
.preview-course-icon { width: 36px; height: 36px; border-radius: 8px; display: flex; align-items: center; justify-content: center; font-size: 1rem; flex-shrink: 0; }
.preview-course-icon.lime { background: var(--lime); }
.preview-course-icon.purple { background: #a78bfa; }
.preview-course-icon.orange { background: #fb923c; }
.preview-course-title { font-weight: 600; font-size: 0.9rem; color: var(--white); }
.preview-course-sub { font-size: 0.75rem; color: rgba(255,255,255,0.5); }
.preview-progress { width: 80px; height: 6px; background: rgba(255,255,255,0.15); border-radius: 3px; margin-left: auto; overflow: hidden; }
.preview-progress-fill { height: 100%; background: var(--lime); border-radius: 3px; }

/* ── Stats Bar ── */
.stats-bar { background: var(--lime); padding: 40px 0; }
.stats-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 24px; text-align: center; }
.stat-item .stat-num { font-size: clamp(2rem, 4vw, 3rem); font-weight: 900; color: var(--black); line-height: 1; }
.stat-item .stat-label { font-size: 0.95rem; color: rgba(0,0,0,0.65); margin-top: 6px; font-weight: 500; }

/* ── Section Headers ── */
.section-header { margin-bottom: 56px; }
.section-tag {
  display: inline-block; background: var(--lime); color: var(--black);
  padding: 4px 14px; border-radius: 50px; font-size: 0.8rem; font-weight: 700;
  letter-spacing: 0.05em; text-transform: uppercase; margin-bottom: 16px;
}
.section-header h2 { margin-bottom: 16px; }
.section-header p { font-size: 1.05rem; color: var(--gray-600); max-width: 560px; }
.section-header.center { text-align: center; }
.section-header.center p { margin: 0 auto; }

/* ── Cards ── */
.card {
  background: var(--white); border-radius: var(--radius); padding: 32px;
  box-shadow: var(--shadow); transition: var(--transition);
  border: 1px solid var(--gray-200);
}
.card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.card-icon {
  width: 52px; height: 52px; border-radius: 12px; background: var(--black);
  display: flex; align-items: center; justify-content: center;
  font-size: 1.4rem; margin-bottom: 20px; flex-shrink: 0;
}
.card-icon.lime { background: var(--lime); }
.card-icon.burgundy { background: var(--burgundy); }
.card h3 { margin-bottom: 10px; }
.card p { font-size: 0.95rem; }

/* ── Products Grid ── */
.products-grid { display: grid; grid-template-columns: repeat(2,1fr); gap: 24px; }
.product-card {
  border-radius: var(--radius-lg); padding: 40px; position: relative; overflow: hidden;
  transition: var(--transition); border: 1px solid var(--gray-200);
}
.product-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.product-card.dark { background: var(--black); color: var(--white); border-color: var(--black); }
.product-card.dark p { color: rgba(255,255,255,0.7); }
.product-card.light { background: var(--gray-50); }
.product-card.lime-bg { background: var(--lime); }
.product-card.burgundy-bg { background: var(--burgundy); color: var(--white); border-color: var(--burgundy); }
.product-card.burgundy-bg p { color: rgba(255,255,255,0.8); }
.product-card h3 { font-size: 1.4rem; margin-bottom: 12px; }
.product-card .product-tag {
  display: inline-block; background: rgba(255,255,255,0.15); color: var(--white);
  padding: 4px 12px; border-radius: 50px; font-size: 0.75rem; font-weight: 600;
  margin-bottom: 16px;
}
.product-card.light .product-tag, .product-card.lime-bg .product-tag {
  background: rgba(0,0,0,0.1); color: var(--black);
}
.product-card .learn-more {
  display: inline-flex; align-items: center; gap: 6px; font-size: 0.9rem; font-weight: 600;
  margin-top: 20px; transition: var(--transition);
}
.product-card.dark .learn-more { color: var(--lime); }
.product-card.light .learn-more { color: var(--black); }
.product-card.lime-bg .learn-more { color: var(--black); }
.product-card.burgundy-bg .learn-more { color: var(--lime); }
.product-card .learn-more:hover { gap: 10px; }

/* ── Why Choose Us Tabs ── */
.why-tabs { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 40px; }
.why-tab {
  padding: 10px 20px; border-radius: 8px; font-size: 0.9rem; font-weight: 600;
  cursor: pointer; border: 2px solid var(--gray-200); background: var(--white);
  color: var(--gray-600); transition: var(--transition);
}
.why-tab.active { background: var(--black); color: var(--lime); border-color: var(--black); }
.why-tab:hover:not(.active) { border-color: var(--black); color: var(--black); }
.why-panel { display: none; }
.why-panel.active { display: grid; grid-template-columns: 1fr 1fr; gap: 32px; align-items: center; }
.why-features { display: flex; flex-direction: column; gap: 16px; }
.why-feature-item { display: flex; align-items: flex-start; gap: 12px; }
.why-check {
  width: 24px; height: 24px; border-radius: 50%; background: var(--lime);
  display: flex; align-items: center; justify-content: center; flex-shrink: 0; margin-top: 2px;
  font-size: 0.75rem; font-weight: 700;
}
.why-visual {
  background: var(--black); border-radius: var(--radius-lg); padding: 32px;
  min-height: 280px; display: flex; align-items: center; justify-content: center;
}
.why-visual-inner { text-align: center; color: var(--white); }
.why-visual-icon { font-size: 3rem; margin-bottom: 16px; }
.why-visual-text { font-size: 1.1rem; font-weight: 600; }

/* ── Testimonials Carousel ── */
.testimonials-section { background: var(--gray-50); }
.carousel { position: relative; overflow: hidden; }
.carousel-track { display: flex; transition: transform 0.5s cubic-bezier(0.4,0,0.2,1); }
.testimonial-card {
  min-width: 380px; max-width: 380px; background: var(--white);
  border-radius: var(--radius); padding: 32px; margin-right: 24px;
  box-shadow: var(--shadow); border: 1px solid var(--gray-200);
  flex-shrink: 0;
}
.testimonial-quote { font-size: 1rem; color: var(--gray-700); line-height: 1.7; margin-bottom: 24px; }
.testimonial-quote::before { content: '"'; font-size: 2rem; color: var(--lime); line-height: 0.5; display: block; margin-bottom: 12px; }
.testimonial-tag { display: inline-block; background: var(--lime); color: var(--black); padding: 3px 10px; border-radius: 50px; font-size: 0.75rem; font-weight: 700; margin-bottom: 12px; }
.testimonial-author { display: flex; align-items: center; gap: 12px; }
.author-avatar {
  width: 44px; height: 44px; border-radius: 50%; display: flex; align-items: center; justify-content: center;
  font-weight: 700; font-size: 1rem; flex-shrink: 0; color: var(--white);
}
.author-name { font-weight: 700; font-size: 0.9rem; }
.author-company { font-size: 0.8rem; color: var(--gray-400); }
.carousel-controls { display: flex; align-items: center; gap: 16px; margin-top: 32px; justify-content: center; }
.carousel-btn {
  width: 44px; height: 44px; border-radius: 50%; border: 2px solid var(--gray-200);
  background: var(--white); cursor: pointer; display: flex; align-items: center; justify-content: center;
  transition: var(--transition); font-size: 1.1rem;
}
.carousel-btn:hover { background: var(--black); color: var(--white); border-color: var(--black); }
.carousel-dots { display: flex; gap: 8px; }
.carousel-dot { width: 8px; height: 8px; border-radius: 50%; background: var(--gray-200); cursor: pointer; transition: var(--transition); }
.carousel-dot.active { background: var(--black); width: 24px; border-radius: 4px; }

/* ── Pricing ── */
.pricing-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px,1fr)); gap: 24px; }
.pricing-card {
  border-radius: var(--radius); padding: 32px; border: 2px solid var(--gray-200);
  position: relative; transition: var(--transition);
}
.pricing-card:hover { border-color: var(--black); box-shadow: var(--shadow); }
.pricing-card.featured { border-color: var(--black); background: var(--black); color: var(--white); }
.pricing-card.featured p { color: rgba(255,255,255,0.75); }
.pricing-badge {
  position: absolute; top: -12px; left: 50%; transform: translateX(-50%);
  background: var(--lime); color: var(--black); padding: 4px 16px;
  border-radius: 50px; font-size: 0.75rem; font-weight: 700; white-space: nowrap;
}
.pricing-tier { font-size: 0.85rem; font-weight: 600; text-transform: uppercase; letter-spacing: 0.05em; color: var(--gray-400); margin-bottom: 8px; }
.pricing-card.featured .pricing-tier { color: var(--lime); }
.pricing-price { font-size: 2.5rem; font-weight: 900; line-height: 1; margin-bottom: 4px; }
.pricing-period { font-size: 0.85rem; color: var(--gray-400); margin-bottom: 20px; }
.pricing-card.featured .pricing-period { color: rgba(255,255,255,0.5); }
.pricing-features { list-style: none; margin-bottom: 28px; display: flex; flex-direction: column; gap: 10px; }
.pricing-features li { display: flex; align-items: center; gap: 8px; font-size: 0.9rem; }
.pricing-features li::before { content: '✓'; color: var(--lime); font-weight: 700; flex-shrink: 0; background: var(--black); width: 18px; height: 18px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 0.65rem; }
.pricing-card.featured .pricing-features li::before { background: var(--lime); color: var(--black); }

/* ── Integrations ── */
.integrations-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(130px, 1fr));
  gap: 16px;
}
.integration-item {
  background: var(--white); border: 1px solid var(--gray-200); border-radius: var(--radius);
  padding: 20px 16px; text-align: center; transition: var(--transition);
}
.integration-item:hover { border-color: var(--black); transform: translateY(-2px); box-shadow: var(--shadow); }
.integration-icon { font-size: 1.8rem; margin-bottom: 8px; }
.integration-name { font-size: 0.8rem; font-weight: 600; color: var(--gray-700); }

/* ── FAQ Accordion ── */
.faq-list { max-width: 720px; margin: 0 auto; display: flex; flex-direction: column; gap: 12px; }
.faq-item {
  border: 1px solid var(--gray-200); border-radius: var(--radius);
  overflow: hidden; transition: var(--transition);
}
.faq-item.open { border-color: var(--black); }
.faq-question {
  width: 100%; padding: 20px 24px; background: var(--white); border: none;
  display: flex; align-items: center; justify-content: space-between;
  cursor: pointer; font-size: 1rem; font-weight: 600; text-align: left;
  transition: var(--transition); gap: 16px;
}
.faq-question:hover { background: var(--gray-50); }
.faq-item.open .faq-question { background: var(--black); color: var(--white); }
.faq-chevron {
  width: 28px; height: 28px; border-radius: 50%; border: 2px solid var(--gray-200);
  display: flex; align-items: center; justify-content: center; flex-shrink: 0;
  transition: var(--transition); font-size: 0.75rem;
}
.faq-item.open .faq-chevron { background: var(--lime); border-color: var(--lime); color: var(--black); transform: rotate(180deg); }
.faq-answer {
  max-height: 0; overflow: hidden; transition: max-height 0.4s ease, padding 0.3s ease;
  padding: 0 24px;
}
.faq-answer-inner { padding: 20px 0; font-size: 0.95rem; color: var(--gray-600); line-height: 1.7; }
.faq-item.open .faq-answer { max-height: 300px; }

/* ── CTA Banner ── */
.cta-banner {
  background: var(--black); color: var(--white); padding: 80px 0; text-align: center;
}
.cta-banner h2 { color: var(--white); margin-bottom: 16px; }
.cta-banner p { color: rgba(255,255,255,0.75); margin-bottom: 36px; font-size: 1.05rem; max-width: 500px; margin-left: auto; margin-right: auto; }
.cta-banner .btn-ctas { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }

/* ── Footer ── */
footer {
  background: var(--black); color: var(--white); padding: 64px 0 32px;
}
.footer-grid {
  display: grid; grid-template-columns: 1.5fr repeat(4, 1fr); gap: 40px; margin-bottom: 48px;
}
.footer-brand .nav-logo { margin-bottom: 16px; font-size: 1.3rem; }
.footer-brand p { font-size: 0.9rem; color: rgba(255,255,255,0.6); max-width: 240px; line-height: 1.6; }
.footer-col h4 { font-size: 0.85rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.08em; color: rgba(255,255,255,0.4); margin-bottom: 16px; }
.footer-col ul { list-style: none; display: flex; flex-direction: column; gap: 10px; }
.footer-col ul li a { font-size: 0.9rem; color: rgba(255,255,255,0.7); transition: var(--transition); }
.footer-col ul li a:hover { color: var(--lime); }
.footer-bottom { border-top: 1px solid rgba(255,255,255,0.1); padding-top: 28px; display: flex; align-items: center; justify-content: space-between; flex-wrap: gap; }
.footer-bottom p { font-size: 0.85rem; color: rgba(255,255,255,0.4); }

/* ── Feature Grids ── */
.features-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 24px; }
.feature-card { padding: 28px; background: var(--gray-50); border-radius: var(--radius); border: 1px solid var(--gray-200); }
.feature-icon { font-size: 2rem; margin-bottom: 16px; }
.feature-card h3 { margin-bottom: 8px; }

/* ── Two-column layout ── */
.two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 64px; align-items: center; }
.two-col.reverse { direction: rtl; }
.two-col.reverse > * { direction: ltr; }

/* ── Benefit list ── */
.benefit-list { list-style: none; display: flex; flex-direction: column; gap: 16px; margin-top: 24px; }
.benefit-list li { display: flex; align-items: flex-start; gap: 12px; }
.benefit-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--lime); flex-shrink: 0; margin-top: 8px; }

/* ── Tools Grid ── */
.tools-section { background: var(--black); color: var(--white); }
.tools-section .section-header h2 { color: var(--white); }
.tools-category-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(180px,1fr)); gap: 20px; }
.tools-category {
  background: rgba(255,255,255,0.06); border: 1px solid rgba(255,255,255,0.1);
  border-radius: var(--radius); padding: 24px;
}
.tools-category h4 { color: var(--lime); margin-bottom: 12px; font-size: 0.8rem; text-transform: uppercase; letter-spacing: 0.08em; }
.tools-category ul { list-style: none; display: flex; flex-direction: column; gap: 8px; }
.tools-category ul li { font-size: 0.875rem; color: rgba(255,255,255,0.75); }

/* ── Steps ── */
.steps-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 32px; position: relative; }
.steps-grid::before {
  content: ''; position: absolute; top: 28px; left: calc(16.67% + 16px); right: calc(16.67% + 16px);
  height: 2px; background: var(--gray-200); z-index: 0;
}
.step-item { text-align: center; position: relative; z-index: 1; }
.step-num {
  width: 56px; height: 56px; border-radius: 50%; background: var(--black); color: var(--lime);
  font-size: 1.2rem; font-weight: 800; display: flex; align-items: center; justify-content: center;
  margin: 0 auto 20px;
}
.step-item h3 { margin-bottom: 10px; }

/* ── Spotlight Cards ── */
.spotlight-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 24px; }
.spotlight-card {
  background: var(--black); color: var(--white); border-radius: var(--radius);
  padding: 32px; border: 1px solid rgba(255,255,255,0.1);
  transition: var(--transition);
}
.spotlight-card:hover { transform: translateY(-4px); border-color: var(--lime); }
.spotlight-logo { font-size: 2rem; margin-bottom: 20px; }
.spotlight-card h3 { color: var(--white); margin-bottom: 10px; }
.spotlight-card p { color: rgba(255,255,255,0.7); font-size: 0.9rem; }

/* ── Resources ── */
.resources-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 24px; }
.resource-card {
  background: var(--white); border: 1px solid var(--gray-200); border-radius: var(--radius);
  padding: 28px; transition: var(--transition);
}
.resource-card:hover { border-color: var(--black); box-shadow: var(--shadow); }
.resource-type { font-size: 0.75rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em; color: var(--gray-400); margin-bottom: 12px; }
.resource-card h4 { margin-bottom: 10px; line-height: 1.4; }
.resource-card .read-more { color: var(--black); font-size: 0.875rem; font-weight: 600; display: inline-flex; align-items: center; gap: 6px; margin-top: 16px; transition: var(--transition); }
.resource-card .read-more:hover { gap: 10px; }

/* ── Product Demo Accordion ── */
.demo-accordion {
  border: 2px solid var(--gray-200); border-radius: var(--radius-lg); overflow: hidden;
  margin-top: 32px;
}
.demo-header {
  padding: 20px 28px; background: var(--black); color: var(--white);
  display: flex; align-items: center; justify-content: space-between; cursor: pointer;
}
.demo-header h3 { color: var(--white); font-size: 1rem; }
.demo-toggle {
  width: 32px; height: 32px; border-radius: 50%; background: var(--lime);
  display: flex; align-items: center; justify-content: center; font-size: 0.9rem; font-weight: 700;
  transition: var(--transition); flex-shrink: 0;
}
.demo-body { max-height: 0; overflow: hidden; transition: max-height 0.5s ease; }
.demo-body.open { max-height: 500px; }
.demo-content { padding: 28px; background: var(--gray-50); }
.demo-screen {
  background: var(--black); border-radius: var(--radius); padding: 24px;
  display: grid; grid-template-columns: 1fr 2fr; gap: 20px; min-height: 200px;
}
.demo-sidebar { display: flex; flex-direction: column; gap: 10px; }
.demo-menu-item {
  padding: 10px 14px; border-radius: 8px; background: rgba(255,255,255,0.06);
  font-size: 0.8rem; color: rgba(255,255,255,0.7); cursor: pointer; transition: var(--transition);
}
.demo-menu-item.active { background: var(--lime); color: var(--black); font-weight: 600; }
.demo-main { display: flex; flex-direction: column; gap: 12px; }
.demo-bar { height: 12px; border-radius: 6px; background: rgba(255,255,255,0.1); }
.demo-bar.w90 { width: 90%; }
.demo-bar.w70 { width: 70%; }
.demo-bar.w50 { width: 50%; background: var(--lime); opacity: 0.5; }
.demo-bar.w30 { width: 30%; }

/* ── Value Props ── */
.value-props-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 32px; }
.value-prop { border-left: 4px solid var(--lime); padding-left: 24px; }
.value-prop h3 { margin-bottom: 8px; }

/* ── File Types ── */
.file-types-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(150px,1fr)); gap: 16px; }
.file-type-item {
  background: var(--gray-50); border: 1px solid var(--gray-200); border-radius: var(--radius);
  padding: 20px 16px; text-align: center; transition: var(--transition);
}
.file-type-item:hover { background: var(--black); color: var(--white); border-color: var(--black); }
.file-type-item:hover .file-type-icon { color: var(--lime); }
.file-type-icon { font-size: 2rem; margin-bottom: 10px; }
.file-type-name { font-size: 0.85rem; font-weight: 600; }

/* ── Hero sub-pages ── */
.hero-sub { background: var(--black); color: var(--white); padding: 80px 0 64px; }
.hero-sub::before {
  content: ''; position: absolute; inset: 0;
  background: radial-gradient(ellipse 60% 50% at 60% 50%, rgba(127,42,35,0.3) 0%, transparent 70%);
  pointer-events: none;
}
.hero-sub { position: relative; }
